private val cells = mutable.HashMap.empty[(Int, Int), ListBuffer[Entity]]

def insert(e: Entity): Unit =
  cells.getOrElseUpdate((cellX(e.x), cellY(e.y)), ListBuffer.empty) += e

def near(x: Double, y: Double, r: Double): Seq[Entity] =
  for {
    cx <- cellX(x - r) to cellX(x + r)
    cy <- cellY(y - r) to cellY(y + r)
    e  <- cells.getOrElse((cx, cy), Nil)
    if e.distanceTo(x, y) <= r
  } yield e
